CREATE TABLE P360_DEAD_LETTERS (ID VARCHAR2(64) PRIMARY KEY, DLQ VARCHAR2(60) NOT NULL, ORIGINAL_QUEUE VARCHAR2(60), ORIGINAL_EXCHANGE VARCHAR2(60), ORIGINAL_ROUTING_KEY VARCHAR2(150), REASON VARCHAR2(40), DEATH_COUNT NUMBER(19) NOT NULL, EVENT_ID VARCHAR2(36), TYPE VARCHAR2(40), ARCHIVED_AT TIMESTAMP WITH TIME ZONE NOT NULL, PAYLOAD CLOB NOT NULL);
CREATE INDEX IDX_DEAD_LETTER_ARCHIVED ON P360_DEAD_LETTERS(ARCHIVED_AT);
